      {
        "parameters": {
          "jsCode": "const init = $('Initialize Parameters').first().json;\n\n// Try to get project from Load Project (existing) or Prepare Project Context (new)\nlet project = $('Load Project').first()?.json || {};\nif (!project.id) {\n  // For new projects, get from Prepare Project Context\n  project = $('Prepare Project Context').first()?.json || {};\n}\n\nconst job = $json;\nreturn [{ json: { ...init, projectId: project.id || project.projectId, projectSlug: project.slug || project.projectSlug, projectName: project.name || project.projectName || project.slug, jobId: job.id } }];",
          "mode": "runOnceForAllItems"
        },
        "id": "pass-context",
        "name": "Pass Context",
