        "id": "load-brd",
        "name": "Load BRD",
        "type": "n8n-nodes-base.postgres",
        "typeVersion": 2.6,
        "position": [
          1440,
          304
        ],
        "alwaysOutputData": true,
        "credentials": {
          "postgres": {
