      {
        "parameters": {
          "jsCode": "// Collect BRD from either DB, existing BRD, or generated from requirements\nconst ctx = $('Pass Context').first().json;\nconst brdSource = $json.brdSource || 'db';\n\nlet brd;\nif (brdSource === 'db') {\n  // From database via Use Existing BRD\n  const dbContent = $('Determine BRD Flow').first().json.brdFromDb;\n  brd = dbContent || {};\n} else if (brdSource === 'generated') {\n  // From generated BRD via Format Generated BRD\n  try {\n    const msgContent = $json.message?.content;\n    if (typeof msgContent === 'string') {\n      brd = JSON.parse(msgContent);\n    } else {\n      brd = msgContent || {};\n    }\n  } catch (e) {\n    brd = { type: 'brd', title: 'Generated BRD', executiveSummary: 'BRD generated from requirements' };\n  }\n} else {\n  // Direct requirements (fallback)\n  const requirements = $('Initialize Parameters').first().json.requirements || '';\n  if (requirements.startsWith('{')) {\n    try {\n      brd = JSON.parse(requirements);\n    } catch (e) {\n      brd = { type: 'requirements', content: requirements };\n    }\n  } else {\n    brd = { type: 'requirements', content: requirements };\n  }\n}\n\nreturn [{ json: { ...ctx, brd, brdSource } }];"
        },
        "id": "collect-brd",
        "name": "Collect BRD",
        "type": "n8n-nodes-base.code",
        "typeVersion": 2,
        "position": [
          2160,
          304
        ]
      },
      {
        "parameters": {
          "method": "POST",
          "url": "http://ollama:11434/api/chat",
          "sendBody": true,
          "specifyBody": "json",
          "jsonBody": "={{ {\n  model: $('Initialize Parameters').first().json.ollamaModel,\n  messages: [\n    {\n      role: 'system',\n      content: 'You are an Enterprise Architect extracting ArchiMate Motivation Layer elements.\\n\\nFrom the parsed document, extract these element types:\\n\\n1. STAKEHOLDERS - Organizations or groups with interest in the system\\n2. DRIVERS - Problems, challenges, or concerns that motivate change\\n3. GOALS - Measurable objectives to be achieved\\n4. OUTCOMES - Expected tangible results\\n\\nOUTPUT FORMAT - Return a JSON object with arrays. Each array item MUST have exactly these fields:\\n- id: unique identifier using format id-{type}-{kebab-case-name}\\n- name: human readable name\\n- type: the ArchiMate type\\n\\nExample of CORRECT format:\\n{\\n  \"stakeholders\": [{\"id\": \"id-sh-system-admin\", \"name\": \"System Administrator\", \"type\": \"Stakeholder\"}],\\n  \"drivers\": [{\"id\": \"id-dr-security-concern\", \"name\": \"Security Concerns\", \"type\": \"Driver\"}],\\n  \"goals\": [{\"id\": \"id-gl-improve-security\", \"name\": \"Improve System Security\", \"type\": \"Goal\"}],\\n  \"outcomes\": [{\"id\": \"id-oc-reduced-breaches\", \"name\": \"Reduced Security Breaches\", \"type\": \"Outcome\"}]\\n}\\n\\nIMPORTANT:\\n- Extract elements from the ACTUAL document content, not from examples\\n- Each element MUST have id, name, and type fields\\n- IDs must be unique and follow the id-{type}-{kebab-case} pattern'\n    },\n    { role: 'user', content: $('Step 0: Parse Document Structure').isExecuted ? ($('Step 0: Parse Document Structure').first().json.message?.content || '') : JSON.stringify($('Collect BRD').first().json.brd || {}) }\n  ],\n  stream: false,\n  format: {\n    type: 'object',\n    required: ['stakeholders', 'drivers', 'goals', 'outcomes'],\n    properties: {\n      stakeholders: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      drivers: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      goals: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      outcomes: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } }\n    }\n  },\n  options: {\n    temperature: $('Initialize Parameters').first().json.ollamaTemperature,\n    seed: $('Initialize Parameters').first().json.ollamaSeed\n  }\n} }}",
          "options": {
            "timeout": 300000
          }
        },
        "id": "gen-business",
        "name": "Step 1: Extract Motivation Layer",
        "type": "n8n-nodes-base.httpRequest",
        "typeVersion": 4.3,
        "position": [
          2400,
          304
        ],
        "retryOnFail": true
      },
      {
        "parameters": {
          "jsCode": "// Validate Step 1: Motivation Layer output\nconst input = $input.first().json;\n\nlet motivation;\ntry {\n  const content = input.message?.content || input;\n  motivation = typeof content === 'string' ? JSON.parse(content) : content;\n} catch (e) {\n  throw new Error('Failed to parse Motivation Layer JSON: ' + e.message);\n}\n\nconst required = ['stakeholders', 'drivers', 'goals', 'outcomes'];\nfor (const key of required) {\n  if (!Array.isArray(motivation[key])) {\n    motivation[key] = [];\n  }\n}\n\nconst validateIds = (arr, prefix) => {\n  return arr.map(el => {\n    if (!el.id || !el.id.startsWith(prefix)) {\n      el.id = prefix + (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);\n    }\n    if (!el.type) el.type = prefix.replace('id-', '').replace(/-/g, '');\n    return el;\n  });\n};\n\nmotivation.stakeholders = validateIds(motivation.stakeholders, 'id-sh-');\nmotivation.drivers = validateIds(motivation.drivers, 'id-dr-');\nmotivation.goals = validateIds(motivation.goals, 'id-gl-');\nmotivation.outcomes = validateIds(motivation.outcomes, 'id-oc-');\n\nreturn [{ json: { motivation } }];"
        },
        "id": "val-business",
        "name": "Validate Motivation Layer",
        "type": "n8n-nodes-base.code",
        "typeVersion": 2,
        "position": [
          2160,
          304
        ]
      },
      {
        "parameters": {
          "operation": "executeQuery",
          "query": "WITH next_version AS (SELECT COALESCE(MAX(version), 0) + 1 AS v FROM architecture.artifacts WHERE project_id = $1 AND type = 'motivation_layer') INSERT INTO architecture.artifacts (project_id, type, version, content, content_hash, meta) SELECT $1, 'motivation_layer', next_version.v, $2::jsonb, md5($2), $3::jsonb FROM next_version RETURNING id, version;",
          "options": {
            "queryReplacement": "={{ [ $('Pass Context').first().json.projectId, JSON.stringify($json.motivation), JSON.stringify({ jobId: $('Pass Context').first().json.jobId }) ] }}"
          }
        },
        "id": "store-business",
        "name": "Store Motivation Layer",
        "type": "n8n-nodes-base.postgres",
        "typeVersion": 2.6,
        "position": [
          2400,
          304
        ],
        "credentials": {
          "postgres": {
            "id": "M5eIfNwtZu8y3dOp",
            "name": "Postgres account"
          }
        }
      },
      {
        "parameters": {
          "method": "POST",
          "url": "http://ollama:11434/api/chat",
          "sendBody": true,
          "specifyBody": "json",
          "jsonBody": "={{ {\n  model: $('Initialize Parameters').first().json.ollamaModel,\n  messages: [\n    {\n      role: 'system',\n      content: 'You are an Enterprise Architect extracting ArchiMate Strategy Layer elements.\\n\\nFrom the parsed document and motivation layer, extract:\\n\\n1. COURSES OF ACTION - Major initiatives that address outcomes\\n2. CAPABILITIES - Business capabilities needed (MUST use reference model when provided)\\n3. RESOURCES - External APIs and data sources\\n\\nCAPABILITY MATCHING RULES:\\n- If matched capabilities are provided from the reference model, USE THEM\\n- Use the exact capability name and path from the reference model\\n- Only add additional capabilities if clearly needed and not in reference model\\n- Prefer L2/L3 level capabilities over L1\\n\\nOUTPUT FORMAT - Return a JSON object with arrays. Each array item MUST have exactly these fields:\\n- id: unique identifier using format id-{type}-{kebab-case-name}\\n- name: human readable name\\n- type: the ArchiMate type\\n\\nFor capabilities from reference model, also include:\\n- path: the full capability path\\n- level: the capability level (1, 2, 3, or 4)\\n\\nIMPORTANT:\\n- Prioritize matched capabilities from the reference model\\n- Each element MUST have id, name, and type fields\\n- IDs must be unique'\n    },\n    {\n      role: 'user',\n      content: '## Parsed Document Structure\\n' + ($('Step 0: Parse Document Structure').isExecuted ? ($('Step 0: Parse Document Structure').first().json.message?.content || '') : JSON.stringify($('Collect BRD').first().json.brd || {})) + '\\n\\n## Motivation Layer\\n' + JSON.stringify($('Validate Motivation Layer').first().json.motivation || {}, null, 2) + '\\n\\n## Matched Capabilities from Healthcare Reference Model\\n' + JSON.stringify($('Match Capabilities (Qdrant)').first().json.matchedCapabilities || [], null, 2) + '\\n\\nNote: Use the matched capabilities above when they align with the document requirements.'\n    }\n  ],\n  stream: false,\n  format: {\n    type: 'object',\n    required: ['coursesOfAction', 'capabilities', 'resources'],\n    properties: {\n      coursesOfAction: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      capabilities: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'}, path: {type: 'string'}, level: {type: 'number'} } } },\n      resources: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } }\n    }\n  },\n  options: {\n    temperature: $('Initialize Parameters').first().json.ollamaTemperature,\n    seed: $('Initialize Parameters').first().json.ollamaSeed\n  }\n} }}",
          "options": {
            "timeout": 300000
          }
        },
        "id": "gen-app",
        "name": "Step 2: Extract Strategy Layer",
        "type": "n8n-nodes-base.httpRequest",
        "typeVersion": 4.3,
        "position": [
          2640,
          304
        ],
        "retryOnFail": true
      },
      {
        "parameters": {
          "jsCode": "// Validate Step 2: Strategy Layer output\nconst input = $input.first().json;\n\nlet strategy;\ntry {\n  const content = input.message?.content || input;\n  strategy = typeof content === 'string' ? JSON.parse(content) : content;\n} catch (e) {\n  throw new Error('Failed to parse Strategy Layer JSON: ' + e.message);\n}\n\nconst required = ['coursesOfAction', 'capabilities', 'resources'];\nfor (const key of required) {\n  if (!Array.isArray(strategy[key])) {\n    strategy[key] = [];\n  }\n}\n\nconst validateIds = (arr, prefix) => {\n  return arr.map(el => {\n    if (!el.id || !el.id.startsWith(prefix)) {\n      el.id = prefix + (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);\n    }\n    return el;\n  });\n};\n\nstrategy.coursesOfAction = validateIds(strategy.coursesOfAction, 'id-coa-');\nstrategy.capabilities = validateIds(strategy.capabilities, 'id-cap-');\nstrategy.resources = validateIds(strategy.resources, 'id-res-');\n\nreturn [{ json: { strategy } }];"
        },
        "id": "val-app",
        "name": "Validate Strategy Layer",
        "type": "n8n-nodes-base.code",
        "typeVersion": 2,
        "position": [
          2880,
          304
        ]
      },
      {
        "parameters": {
          "operation": "executeQuery",
          "query": "WITH next_version AS (SELECT COALESCE(MAX(version), 0) + 1 AS v FROM architecture.artifacts WHERE project_id = $1 AND type = 'strategy_layer') INSERT INTO architecture.artifacts (project_id, type, version, content, content_hash, meta) SELECT $1, 'strategy_layer', next_version.v, $2::jsonb, md5($2), $3::jsonb FROM next_version RETURNING id, version;",
          "options": {
            "queryReplacement": "={{ [ $('Pass Context').first().json.projectId, JSON.stringify($json.strategy), JSON.stringify({ jobId: $('Pass Context').first().json.jobId }) ] }}"
          }
        },
        "id": "store-app",
        "name": "Store Strategy Layer",
        "type": "n8n-nodes-base.postgres",
        "typeVersion": 2.6,
        "position": [
          3120,
          304
        ],
        "credentials": {
          "postgres": {
            "id": "M5eIfNwtZu8y3dOp",
            "name": "Postgres account"
          }
        }
      },
      {
        "parameters": {
          "method": "POST",
          "url": "http://ollama:11434/api/chat",
          "sendBody": true,
          "specifyBody": "json",
          "jsonBody": "={{ {\n  model: $('Initialize Parameters').first().json.ollamaModel,\n  messages: [\n    {\n      role: 'system',\n      content: 'You are an Enterprise Architect extracting ArchiMate Business Layer elements. Extract: ACTORS, PROCESSES, SERVICES, OBJECTS, and USE CASES. Each item needs id, name, type. UseCases also need: actor, trigger, steps array, outcome. IDs format: id-{type}-{kebab-name}'\n    },\n    {\n      role: 'user',\n      content: '## BRD\\n' + JSON.stringify($('Collect BRD').first().json.brd || { }, null, 2) + '\\n\\n## Strategy\\n' + JSON.stringify($('Validate Strategy Layer').first().json.strategy || { }, null, 2)\n    }\n  ],\n  stream: false,\n  format: {\n    type: 'object',\n    required: ['actors', 'processes', 'services', 'objects', 'useCases'],\n    properties: {\n      actors: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string' }, name: {type: 'string' }, type: {type: 'string' } } } },\n      processes: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string' }, name: {type: 'string' }, type: {type: 'string' } } } },\n      services: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string' }, name: {type: 'string' }, type: {type: 'string' } } } },\n      objects: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string' }, name: {type: 'string' }, type: {type: 'string' } } } },\n      useCases: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type', 'actor', 'trigger', 'steps', 'outcome'], properties: { id: {type: 'string' }, name: {type: 'string' }, type: {type: 'string' }, actor: {type: 'string' }, trigger: {type: 'string' }, steps: {type: 'array', items: {type: 'string' } }, outcome: {type: 'string' } } } }\n    }\n  },\n  options: {\n    temperature: $('Initialize Parameters').first().json.ollamaTemperature,\n    seed: $('Initialize Parameters').first().json.ollamaSeed\n  }\n} }}",
          "options": {
            "timeout": 300000
          }
        },
        "id": "gen-data",
        "name": "Step 3: Extract Business Layer",
        "type": "n8n-nodes-base.httpRequest",
        "typeVersion": 4.3,
        "position": [
          3360,
          304
        ],
        "retryOnFail": true
      },
      {
        "parameters": {
          "jsCode": "// Validate Step 3: Business Layer output\nconst input = $input.first().json;\n\nlet businessArch;\ntry {\n  const content = input.message?.content || input;\n  businessArch = typeof content === 'string' ? JSON.parse(content) : content;\n} catch (e) {\n  throw new Error('Failed to parse Business Layer JSON: ' + e.message);\n}\n\nconst required = ['actors', 'processes', 'services', 'objects'];\nfor (const key of required) {\n  if (!Array.isArray(businessArch[key])) {\n    businessArch[key] = [];\n  }\n}\n\n// Initialize useCases if not present\nif (!Array.isArray(businessArch.useCases)) {\n  businessArch.useCases = [];\n}\n\nconst validateIds = (arr, prefix) => {\n  return arr.map(el => {\n    if (!el.id || !el.id.startsWith(prefix)) {\n      el.id = prefix + (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);\n    }\n    return el;\n  });\n};\n\nbusinessArch.actors = validateIds(businessArch.actors, 'id-ba-');\nbusinessArch.processes = validateIds(businessArch.processes, 'id-bp-');\nbusinessArch.services = validateIds(businessArch.services, 'id-bs-');\nbusinessArch.objects = validateIds(businessArch.objects, 'id-bo-');\n\n// Validate use cases\nbusinessArch.useCases = businessArch.useCases.map(uc => {\n  // Generate ID if missing\n  if (!uc.id || !uc.id.startsWith('id-uc-')) {\n    uc.id = 'id-uc-' + (uc.name || 'use-case').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);\n  }\n  // Ensure type is set\n  if (!uc.type) uc.type = 'BusinessInteraction';\n  // Ensure steps is an array\n  if (!Array.isArray(uc.steps)) uc.steps = [];\n  // Ensure required fields exist\n  if (!uc.trigger) uc.trigger = '';\n  if (!uc.outcome) uc.outcome = '';\n  if (!uc.actor) uc.actor = businessArch.actors[0]?.id || '';\n  return uc;\n});\n\nreturn [{ json: { businessArch } }];"
        },
        "id": "val-data",
        "name": "Validate Business Layer",
        "type": "n8n-nodes-base.code",
        "typeVersion": 2,
        "position": [
          3600,
