        ]
      },
      {
        "parameters": {
          "operation": "executeQuery",
          "query": "WITH next_version AS (SELECT COALESCE(MAX(version), 0) + 1 AS v FROM architecture.artifacts WHERE project_id = $1 AND type = 'business_layer') INSERT INTO architecture.artifacts (project_id, type, version, content, content_hash, meta) SELECT $1, 'business_layer', next_version.v, $2::jsonb, md5($2), $3::jsonb FROM next_version RETURNING id, version;",
