        "parameters": {
          "jsCode": "// Convert all architecture layers to ArchiMate 3.0 Exchange Format XML\n// Implements Steps 5-8 of the doc-to-archimate formula\n\nconst ctx = $('Pass Context').first().json;\nconst motVal = $('Validate Motivation Layer').first().json;\nconst stratVal = $('Validate Strategy Layer').first().json;\nconst bizVal = $('Validate Business Layer').first().json;\nconst appVal = $('Validate Application Layer').first().json;\n\n// Extract layer data\nconst motivation = motVal.motivation || {};\nconst strategy = stratVal.strategy || {};\nconst business = bizVal.businessArch || {};\nconst application = appVal.applicationArch || {};\n\n// Utilities\nconst escXml = (s) => String(s || '').replace(/&/g, '&amp;').replace(/\"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, '&apos;');\nconst fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };\n\n// ArchiMate type mapping\nconst typeMap = {\n  'Stakeholder': 'Stakeholder', 'Driver': 'Driver', 'Goal': 'Goal', 'Outcome': 'Outcome',\n  'CourseOfAction': 'CourseOfAction', 'Capability': 'Capability', 'Resource': 'Resource',\n  'BusinessActor': 'BusinessActor', 'BusinessProcess': 'BusinessProcess',\n  'BusinessService': 'BusinessService', 'BusinessObject': 'BusinessObject',\n  'ApplicationComponent': 'ApplicationComponent', 'ApplicationService': 'ApplicationService',\n  'ApplicationInterface': 'ApplicationInterface', 'DataObject': 'DataObject', 'ApplicationEvent': 'ApplicationEvent'\n};\n\n// Collect all elements\nconst elements = [];\nconst addElements = (arr, defaultType) => {\n  for (const el of (arr || [])) {\n    if (!el || !el.id) continue;\n    const archType = typeMap[el.type] || defaultType;\n    elements.push({ id: el.id, name: el.name || el.id, type: archType, layer: el.layer });\n  }\n};\n\n// Add elements from each layer\naddElements(motivation.stakeholders, 'Stakeholder');\naddElements(motivation.drivers, 'Driver');\naddElements(motivation.goals, 'Goal');\naddElements(motivation.outcomes, 'Outcome');\naddElements(strategy.coursesOfAction, 'CourseOfAction');\naddElements(strategy.capabilities, 'Capability');\naddElements(strategy.resources, 'Resource');\naddElements(business.actors, 'BusinessActor');\naddElements(business.processes, 'BusinessProcess');\naddElements(business.services, 'BusinessService');\naddElements(business.objects, 'BusinessObject');\naddElements(application.components, 'ApplicationComponent');\naddElements(application.services, 'ApplicationService');\naddElements(application.interfaces, 'ApplicationInterface');\naddElements(application.dataObjects, 'DataObject');\naddElements(application.events, 'ApplicationEvent');\n\n// STEP 5: Generate Relationships\nconst relationships = [];\nlet relCounter = 1;\n\n// Stakeholder -> Driver (Association)\nfor (const sh of (motivation.stakeholders || [])) {\n  for (const dr of (motivation.drivers || [])) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: sh.id, target: dr.id, type: 'Association' });\n  }\n}\n\n// Driver -> Goal (Influence)\nfor (const dr of (motivation.drivers || [])) {\n  for (const gl of (motivation.goals || [])) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: dr.id, target: gl.id, type: 'Influence' });\n  }\n}\n\n// Outcome -> Goal (Realization)\nfor (const oc of (motivation.outcomes || [])) {\n  for (const gl of (motivation.goals || [])) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: oc.id, target: gl.id, type: 'Realization' });\n  }\n}\n\n// CourseOfAction -> Outcome (Realization)\nfor (const coa of (strategy.coursesOfAction || [])) {\n  for (const oc of (motivation.outcomes || []).slice(0, 2)) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: coa.id, target: oc.id, type: 'Realization' });\n  }\n}\n\n// Capability -> CourseOfAction (Realization)\nfor (const cap of (strategy.capabilities || [])) {\n  for (const coa of (strategy.coursesOfAction || []).slice(0, 2)) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: cap.id, target: coa.id, type: 'Realization' });\n  }\n}\n\n// BusinessProcess -> Capability (Realization)\nfor (const bp of (business.processes || [])) {\n  for (const cap of (strategy.capabilities || []).slice(0, 2)) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: bp.id, target: cap.id, type: 'Realization' });\n  }\n}\n\n// ApplicationService -> BusinessProcess (Serving)\nfor (const as of (application.services || [])) {\n  for (const bp of (business.processes || []).slice(0, 2)) {\n    relationships.push({ id: `id-rel-${String(relCounter++).padStart(3, '0')}`, source: as.id, target: bp.id, type: 'Serving' });\n  }\n}\n\n// STEP 6: Generate Organizations\nconst genOrgItem = (label, refs) => {\n  if (!refs || refs.length === 0) return '';\n  const items = refs.map(r => `      <item><idRef>${escXml(r.id)}</idRef></item>`).join('\\n');\n  return `    <item>\\n      <label xml:lang=\"en\">${escXml(label)}</label>\\n${items}\\n    </item>`;\n};\n\nlet orgXml = '  <organizations>\\n';\norgXml += genOrgItem('Motivation', [...(motivation.stakeholders||[]), ...(motivation.drivers||[]), ...(motivation.goals||[]), ...(motivation.outcomes||[])]);\norgXml += '\\n';\norgXml += genOrgItem('Strategy', [...(strategy.coursesOfAction||[]), ...(strategy.capabilities||[]), ...(strategy.resources||[])]);\norgXml += '\\n';\norgXml += genOrgItem('Business', [...(business.actors||[]), ...(business.processes||[]), ...(business.services||[]), ...(business.objects||[])]);\norgXml += '\\n';\norgXml += genOrgItem('Application', [...(application.components||[]), ...(application.services||[]), ...(application.interfaces||[]), ...(application.dataObjects||[]), ...(application.events||[])]);\norgXml += '\\n';\norgXml += genOrgItem('Relations', relationships);\norgXml += '\\n  </organizations>';\n\n// STEP 7: Generate Views\nlet appViewNodes = '';\nlet y = 50;\nconst nodeWidth = 180, nodeHeight = 60, gap = 30;\nlet x = 50;\n\nfor (const comp of (application.components || [])) {\n  const isExternal = comp.id.includes('-ext-');\n  const [r, g, b] = isExternal ? [213, 213, 213] : [181, 211, 231];\n  appViewNodes += `      <node xsi:type=\"Element\" identifier=\"view-node-${fnv1a(comp.id)}\" elementRef=\"${escXml(comp.id)}\" x=\"${x}\" y=\"${y}\" w=\"${nodeWidth}\" h=\"${nodeHeight}\">\\n        <style><fillColor r=\"${r}\" g=\"${g}\" b=\"${b}\"/></style>\\n      </node>\\n`;\n  x += nodeWidth + gap;\n  if (x > 800) { x = 50; y += nodeHeight + gap; }\n}\n\nlet viewsXml = `  <views>\\n    <diagrams>\\n      <view identifier=\"id-view-application\" xsi:type=\"Diagram\">\\n        <name xml:lang=\"en\">Application Architecture</name>\\n${appViewNodes}      </view>\\n    </diagrams>\\n  </views>`;\n\n// STEP 8: Assemble Final XML\nlet elementsXml = '  <elements>\\n';\nfor (const el of elements) {\n  elementsXml += `    <element identifier=\"${escXml(el.id)}\" xsi:type=\"${escXml(el.type)}\">\\n      <name xml:lang=\"en\">${escXml(el.name)}</name>\\n    </element>\\n`;\n}\nelementsXml += '  </elements>';\n\nlet relationshipsXml = '  <relationships>\\n';\nfor (const rel of relationships) {\n  relationshipsXml += `    <relationship identifier=\"${escXml(rel.id)}\" source=\"${escXml(rel.source)}\" target=\"${escXml(rel.target)}\" xsi:type=\"${escXml(rel.type)}\"/>\\n`;\n}\nrelationshipsXml += '  </relationships>';\n\nconst modelId = 'id-' + fnv1a(ctx.projectName + '-model');\nconst fullXml = `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<model xmlns=\"http://www.opengroup.org/xsd/archimate/3.0/\"\n       xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n       xsi:schemaLocation=\"http://www.opengroup.org/xsd/archimate/3.0/ http://www.opengroup.org/xsd/archimate/3.1/archimate3_Diagram.xsd\"\n       identifier=\"${modelId}\">\n  <name xml:lang=\"en\">${escXml(ctx.projectName)}</name>\n  <documentation xml:lang=\"en\">ArchiMate model generated using doc-to-archimate formula</documentation>\n${elementsXml}\n${relationshipsXml}\n${orgXml}\n${viewsXml}\n</model>`;\n\nreturn [{\n  json: {\n    ...ctx,\n    fullXml,\n    fullXmlHash: fnv1a(fullXml),\n    elementCount: elements.length,\n    relationshipCount: relationships.length\n  }\n}];"
        },
