        "parameters": {
          "jsCode": "const ctx = $('Convert to ArchiMate XML').first().json;\nconst { fullXml, projectSlug, jobId, projectId } = ctx;\n\n// Skip git script if fullXml is missing\nif (!fullXml) {\n  return [{ json: { ...ctx, gitScript: '# No XML to commit', skipGit: true } }];\n}\n\nconst repoDir = '/opt/workspace/software-delivery';\nconst projectDir = repoDir + '/' + projectSlug + '-docs';\nconst orgDir = repoDir + '/org-architecture';\nconst remote = 'git@github.com:shlapolosa/software-delivery.git';\n\n// Escape content for heredoc\nconst safeHeredoc = (content, marker) => content ? content.replace(new RegExp(marker, 'g'), marker + '_ESC') : '';\n\n// Extract element lines from fullXml\nconst elementLines = fullXml.split('\\n').filter(line => line.includes('<element ')).join('\\n');\n\nlet sh = `set -e\nmkdir -p /opt/workspace\n\n# Clone or fetch repo\nif [ ! -d '${repoDir}/.git' ]; then\n  git clone '${remote}' '${repoDir}'\nfi\ncd '${repoDir}'\ngit fetch origin --prune\n\n# Reset and checkout main\ngit reset --hard HEAD 2>/dev/null || true\ngit checkout main 2>/dev/null || git checkout -b main origin/main 2>/dev/null || git checkout -b main\ngit reset --hard origin/main 2>/dev/null || true\ngit pull origin main --rebase 2>/dev/null || true\nmkdir -p '${orgDir}'\n\n# Write elements to temp file\nNEW_ELEMENTS_FILE='/tmp/new_elements_${jobId}.txt'\nMERGED_FILE='/tmp/merged_${jobId}.archimate'\nORG_FILE='${orgDir}/full.archimate'\n\ncat > \"$NEW_ELEMENTS_FILE\" <<'EOFNEW_${jobId}'\n` + elementLines + `\nEOFNEW_${jobId}\n\n# Merge with existing org-architecture\nif [ -f \"$ORG_FILE\" ] && ! grep -q '<<<<<<' \"$ORG_FILE\" 2>/dev/null; then\n  EXISTING_ELEMENTS=$(grep '<element ' \"$ORG_FILE\" 2>/dev/null || true)\n  ALL_ELEMENTS=$(cat \"$NEW_ELEMENTS_FILE\"; echo \"$EXISTING_ELEMENTS\")\n  UNIQUE_ELEMENTS=$(echo \"$ALL_ELEMENTS\" | sort -t'\"' -k4,4 -u | grep -v '^$' || true)\nelse\n  UNIQUE_ELEMENTS=$(cat \"$NEW_ELEMENTS_FILE\")\nfi\n\n# Build merged org-architecture file\ncat > \"$MERGED_FILE\" <<'EOFHDR'\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<archimate:model xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:archimate=\"http://www.archimatetool.com/archimate\" name=\"Organization Architecture\" id=\"org-arch-001\">\n  <folder name=\"Business\" type=\"business\">\nEOFHDR\n\necho \"$UNIQUE_ELEMENTS\" | grep -E 'Capability|BusinessActor|BusinessProcess|BusinessService' >> \"$MERGED_FILE\" || true\ncat >> \"$MERGED_FILE\" <<'EOFBIZ'\n  </folder>\n  <folder name=\"Application\" type=\"application\">\nEOFBIZ\n\necho \"$UNIQUE_ELEMENTS\" | grep -E 'ApplicationComponent|ApplicationInterface|DataObject' >> \"$MERGED_FILE\" || true\ncat >> \"$MERGED_FILE\" <<'EOFTAIL'\n  </folder>\n  <folder name=\"Relations\" type=\"relations\">\n  </folder>\n</archimate:model>\nEOFTAIL\n\nmv \"$MERGED_FILE\" \"$ORG_FILE\"\nrm -f \"$NEW_ELEMENTS_FILE\"\n\ngit add 'org-architecture/full.archimate'\ngit commit -m 'Merge architecture from ${projectSlug} into org-architecture (job ${jobId})' || true\n\nfor i in 1 2 3; do\n  if git push origin main; then\n    echo \"Successfully pushed to main on attempt $i\"\n    break\n  else\n    echo \"Push failed, pulling and retrying (attempt $i)...\"\n    git pull origin main --rebase || git pull origin main -X theirs\n    git add 'org-architecture/full.archimate'\n    git commit -m 'Merge architecture from ${projectSlug} (retry)' || true\n  fi\ndone\n\n# Create project branch and save full.archimate\ngit checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'\nmkdir -p '${projectDir}/architecture'\n\n`;\n\n// Write project full.archimate\nsh += \"cat > '\" + projectDir + \"/architecture/full.archimate' <<'EOFFULL_\" + jobId + \"'\\n\" + safeHeredoc(fullXml, 'EOFFULL_' + jobId) + \"\\nEOFFULL_\" + jobId + \"\\n\";\n\nsh += `\ngit add '${projectSlug}-docs/architecture'\ngit commit -m 'Add architecture for ${projectSlug} (job ${jobId})' || true\ngit push -u origin '${projectSlug}'\n`;\n\nreturn [{ json: { ...ctx, gitScript: sh } }];",
          "mode": "runOnceForAllItems"
        },
