        "name": "Match Capabilities (Qdrant)",
        "type": "n8n-nodes-base.code",
        "typeVersion": 2,
        "position": [
          2100,
          304
        ],
        "parameters": {
          "jsCode": "// Match document concepts to Healthcare Capability Reference Model via Qdrant\nconst step0Content = $('Step 0: Parse Document Structure').first().json.message?.content || '';\nconst motivation = $('Validate Motivation Layer').first().json.motivation || {};\n\n// Extract key business concepts from the parsed document\nconst conceptsToMatch = [];\n\n// Get processes and services mentioned\nconst processMatch = step0Content.match(/###\\s*Processes[\\s\\S]*?(?=###|##|$)/i);\nif (processMatch) {\n  const lines = processMatch[0].split('\\n').filter(l => l.trim().startsWith('-'));\n  lines.forEach(l => conceptsToMatch.push(l.replace(/^-\\s*/, '').trim()));\n}\n\nconst serviceMatch = step0Content.match(/###\\s*Services[\\s\\S]*?(?=###|##|$)/i);\nif (serviceMatch) {\n  const lines = serviceMatch[0].split('\\n').filter(l => l.trim().startsWith('-'));\n  lines.forEach(l => conceptsToMatch.push(l.replace(/^-\\s*/, '').trim()));\n}\n\n// Add goals as capability hints\n(motivation.goals || []).forEach(g => conceptsToMatch.push(g.name));\n\nif (conceptsToMatch.length === 0) {\n  return [{ json: { matchedCapabilities: [], conceptsSearched: 0, passThrough: $json } }];\n}\n\nconst searchQuery = conceptsToMatch.slice(0, 10).join(' ');\n\nlet embedding = null;\ntry {\n  const embeddingResponse = await this.helpers.httpRequest({\n    method: 'POST',\n    url: 'http://ollama:11434/api/embeddings',\n    body: { model: 'nomic-embed-text', prompt: searchQuery },\n    json: true\n  });\n  embedding = embeddingResponse.embedding;\n} catch (e) {\n  return [{ json: { matchedCapabilities: [], error: 'Embedding failed: ' + e.message, passThrough: $json } }];\n}\n\nlet matchedCapabilities = [];\ntry {\n  const qdrantResponse = await this.helpers.httpRequest({\n    method: 'POST',\n    url: 'http://qdrant:6333/collections/capability-maps/points/search',\n    body: { vector: embedding, limit: 15, with_payload: true, score_threshold: 0.60 },\n    json: true\n  });\n  \n  const results = qdrantResponse.result || [];\n  const seen = new Set();\n  results.forEach(hit => {\n    const payload = hit.payload || {};\n    const meta = payload.metadata || {};\n    const level = meta.level || payload.level;\n    const capability = payload.capability || meta.l3 || meta.l2 || meta.l1;\n    const path = payload.path || '';\n    const definition = payload.definition || '';\n    \n    if (capability && !seen.has(capability)) {\n      seen.add(capability);\n      matchedCapabilities.push({\n        id: payload.id || 'cap-' + capability.toLowerCase().replace(/\\s+/g, '-'),\n        level: level,\n        capability: capability,\n        path: path,\n        definition: definition.substring(0, 200),\n        score: hit.score\n      });\n    }\n  });\n  \n  matchedCapabilities.sort((a, b) => {\n    if (a.level !== b.level) return (a.level === 2 || a.level === 3) ? -1 : 1;\n    return b.score - a.score;\n  });\n  matchedCapabilities = matchedCapabilities.slice(0, 10);\n} catch (e) {\n  matchedCapabilities = [];\n}\n\nreturn [{ json: { matchedCapabilities, conceptsSearched: conceptsToMatch.length, searchQuery: searchQuery.substring(0, 200), passThrough: $json } }];",
