'\\n\\n## Use Cases to Support\\n' + JSON.stringify(($('Validate Business Layer').first().json.businessArch?.useCases || []), null, 2)\n    }\n  ],\n  stream: false,\n  format: {\n    type: 'object',\n    required: ['components', 'services', 'interfaces', 'dataObjects', 'events'],\n    properties: {\n      components: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      services: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      interfaces: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      dataObjects: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } },\n      events: { type: 'array', items: { type: 'object', required: ['id', 'name', 'type'], properties: { id: {type: 'string'}, name: {type: 'string'}, type: {type: 'string'} } } }\n    }\n  },\n  options: {\n    temperature: $('Initialize Parameters').first().json.ollamaTemperature,\n    seed: $('Initialize Parameters').first().json.ollamaSeed\n  }\n} }}",
