            "jsCode": "// Validate Step 4: Application Layer output\nconst input = $input.first().json;\n\nlet applicationArch;\ntry {\n  const content = input.message?.content || input;\n  applicationArch = typeof content === 'string' ? JSON.parse(content) : content;\n} catch (e) {\n  throw new Error('Failed to parse Application Layer JSON: ' + e.message);\n}\n\nconst required = ['components', 'services', 'interfaces', 'dataObjects', 'events'];\nfor (const key of required) {\n  if (!Array.isArray(applicationArch[key])) {\n    applicationArch[key] = [];\n  }\n}\n\nconst validateIds = (arr, prefix) => {\n  return arr.map(el => {\n    if (!el.id || !el.id.startsWith(prefix)) {\n      const baseName = (el.name || 'item').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').slice(0, 30);\n      el.id = prefix + baseName;\n    }\n    return el;\n  });\n};\n\napplicationArch.components = validateIds(applicationArch.components, 'id-ac-');\napplicationArch.services = validateIds(applicationArch.services, 'id-as-');\napplicationArch.interfaces = validateIds(applicationArch.interfaces, 'id-ai-');\napplicationArch.dataObjects = validateIds(applicationArch.dataObjects, 'id-do-');\napplicationArch.events = validateIds(applicationArch.events, 'id-ae-');\n\nreturn [{ json: { applicationArch } }];"
