            "jsCode": "// Parse and normalize incoming request\n// Detect Open WebUI system prompts and RAG context formats\nconst input = $json.body || $json;\n\n// Check multiple possible field names for user input\nconst chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';\nconst requirements = input.requirements || '';\n\n// Detect Open WebUI system prompts\nconst isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');\nconst isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');\nconst isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');\nconst isSearchQuery = chatInput.includes('### Task:') && chatInput.includes('generating search queries');\nconst isSystemPrompt = isAutoTag || isFollowUp || isTitleGen || isSearchQuery;\n\n// Also check requirements field for system prompts\nconst reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');\nconst reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');\nconst reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');\nconst reqIsSearchQuery = requirements.includes('### Task:') && requirements.includes('generating search queries');\nconst reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen || reqIsSearchQuery;\n\n// Determine system prompt type\nlet systemPromptType = null;\nif (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';\nelse if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';\nelse if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';\nelse if (isSearchQuery || reqIsSearchQuery) systemPromptType = 'search-query';\n\n// Check if chatInput or requirements contains RAG context\nconst hasRagInChat = chatInput.includes('<context>') && chatInput.includes('<source') && chatInput.includes('</context>');\nconst hasRagInReq = requirements.includes('<context>') && requirements.includes('<source') && requirements.includes('</context>');\nconst hasRagContext = hasRagInChat || hasRagInReq;\n\n// Extract user query from RAG format\nconst userQueryMatch = chatInput.match(/<user_query>([\\s\\S]*?)<\\/user_query>/);\nconst userQueryContent = userQueryMatch ? userQueryMatch[1].trim() : '';\nconst isEmptyUserQuery = hasRagInChat && userQueryContent.length === 0;\n\n// Extract document content from RAG source tags (inline extraction)\nlet ragExtractedContent = '';\nconst textToExtract = hasRagInChat ? chatInput : (hasRagInReq ? requirements : '');\nif (textToExtract && textToExtract.includes('<source')) {\n  const sourceMatches = textToExtract.matchAll(/<source[^>]*>([\\s\\S]*?)<\\/source>/g);\n  const sources = [];\n  for (const match of sourceMatches) {\n    if (match[1] && match[1].trim()) {\n      sources.push(match[1].trim());\n    }\n  }\n  if (sources.length > 0) {\n    ragExtractedContent = [...new Set(sources)].join('\\n\\n');\n  }\n}\n\n// Extract project slug - only use if it looks like a slug (short, no spaces)\nconst inputProjectSlug = input.projectSlug || null;\nconst looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ') && !inputProjectSlug.includes('<');\nconst actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;\n\n// Determine raw input (used for classification)\nlet rawInput = '';\nif (!(isSystemPrompt || reqIsSystemPrompt)) {\n  if (ragExtractedContent) {\n    rawInput = ragExtractedContent;\n  } else if (requirements && requirements.length > 20 && !hasRagInReq) {\n    rawInput = requirements;\n  } else if (chatInput && chatInput.length > 0 && !hasRagInChat) {\n    rawInput = chatInput;\n  } else if (userQueryContent) {\n    rawInput = userQueryContent;\n  }\n}\n\n// Determine mode suggestion\nconst hasSubstantialRequirements = ragExtractedContent.length > 100 || (requirements && requirements.length > 100 && !hasRagInReq);\nconst explicitMode = input.mode || null;\nconst suggestedMode = explicitMode || (hasSubstantialRequirements ? 'execute' : null);\n\n// Set final requirements - prefer extracted RAG content over raw requirements\nlet finalRequirements = null;\nif (ragExtractedContent && ragExtractedContent.length > 100) {\n  finalRequirements = ragExtractedContent;\n} else if (requirements && !hasRagInReq) {\n  finalRequirements = requirements;\n}\n\nreturn [{ json: {\n  rawInput: rawInput,\n  projectSlug: actualProjectSlug,\n  projectName: input.projectName || null,\n  requirements: finalRequirements,\n  sessionId: input.sessionId || null,\n  isSystemPrompt: isSystemPrompt || reqIsSystemPrompt,\n  systemPromptType: systemPromptType,\n  suggestedMode: suggestedMode,\n  hasRagContext: hasRagContext,\n  ragFileUpload: hasRagContext && isEmptyUserQuery\n} }];"
