object',\n          required: ['useCaseId', 'useCaseName', 'trigger', 'actors', 'participants', 'mainFlow'],\n          properties: {\n            useCaseId: { type: 'string' },\n            useCaseName: { type: 'string' },\n            trigger: { type: 'string' },\n            actors: { type: 'array', items: { type: 'string' } },\n            participants: { type: 'array', items: { type: 'string' } },\n            mainFlow: { type: 'array', items: { type: 'object', required: ['from', 'to', 'action'], properties: { from: { type: 'string' }, to: { type: 'string' }, action: { type: 'string' } } } },\n            alternateFlows: { type: 'array', items: { type: 'object', required: ['condition', 'steps'], properties: { condition: { type: 'string' }, steps: { type: 'array', items: { type: 'object', required: ['from', 'to', 'action'], properties: { from: { type: 'string' }, to: { type: 'string' }, action: { type: 'string' } } } } } } }\n          }\n        }\n      }\n    }\n  },\n  options: {\n    temperature: $('Initialize Parameters').first().json.ollamaTemperature,\n    seed: $('Initialize Parameters').first().json.ollamaSeed\n  }\n} }}",
