            "jsCode": "// Validate Sequence Diagrams and generate Markdown output\nconst input = $input.first().json;\nconst appArch = $('Validate Application Layer').first().json.applicationArch || {};\nconst useCases = $('Validate Business Layer').first().json.businessArch?.useCases || [];\nconst actors = $('Validate Business Layer').first().json.businessArch?.actors || [];\n\nlet diagrams;\ntry {\n  const content = input.message?.content || input;\n  diagrams = typeof content === 'string' ? JSON.parse(content) : content;\n} catch (e) {\n  throw new Error('Failed to parse Sequence Diagrams JSON: ' + e.message);\n}\n\nif (!Array.isArray(diagrams.sequenceDiagrams)) {\n  diagrams.sequenceDiagrams = [];\n}\n\n// Get all component names from application architecture\nconst allComponents = new Set();\n['components', 'services', 'interfaces'].forEach(key => {\n  (appArch[key] || []).forEach(c => allComponents.add(c.name));\n});\n\n// Add actors\nactors.forEach(a => allComponents.add(a.name));\n\n// Common actor aliases that are valid\nconst validAliases = ['User', 'Actor', 'System', 'External System'];\n\n// Validate and enrich each diagram\nconst validatedDiagrams = diagrams.sequenceDiagrams.map(d => {\n  const missingComponents = [];\n  const participants = new Set(d.participants || []);\n  \n  const checkParticipant = (name) => {\n    if (!name) return;\n    if (allComponents.has(name) || validAliases.includes(name)) return;\n    // Fuzzy match\n    const match = Array.from(allComponents).find(c => \n      c.toLowerCase().includes(name.toLowerCase()) || \n      name.toLowerCase().includes(c.toLowerCase())\n    );\n    if (!match) missingComponents.push(name);\n  };\n  \n  // Check main flow participants\n  (d.mainFlow || []).forEach(step => {\n    checkParticipant(step.from);\n    checkParticipant(step.to);\n    participants.add(step.from);\n    participants.add(step.to);\n  });\n  \n  // Check alternate flows participants\n  (d.alternateFlows || []).forEach(alt => {\n    (alt.steps || []).forEach(step => {\n      checkParticipant(step.from);\n      checkParticipant(step.to);\n      participants.add(step.from);\n      participants.add(step.to);\n    });\n  });\n  \n  return {\n    ...d,\n    participants: Array.from(participants),\n    validation: {\n      allComponentsMapped: missingComponents.length === 0,\n      missingComponents: [...new Set(missingComponents)]\n    }\n  };\n});\n\n// Generate Markdown output\nlet markdown = '# Sequence Diagrams\\n\\n';\nlet allValid = true;\n\nvalidatedDiagrams.forEach((d, idx) => {\n  markdown += `## ${idx + 1}. ${d.useCaseName}\\n\\n`;\n  markdown += `**Use Case ID:** \\`${d.useCaseId}\\`\\n\\n`;\n  markdown += `**Trigger:** ${d.trigger || 'N/A'}\\n\\n`;\n  markdown += `**Actors:** ${(d.actors || []).join(', ') || 'N/A'}\\n\\n`;\n  markdown += `**Participants:** ${d.participants.join(', ')}\\n\\n`;\n  \n  markdown += `### Main Flow\\n\\n`;\n  markdown += `| # | From | To | Action |\\n`;\n  markdown += `|---|------|-----|--------|\\n`;\n  (d.mainFlow || []).forEach((step, stepIdx) => {\n    markdown += `| ${stepIdx + 1} | ${step.from} | ${step.to} | ${step.action} |\\n`;\n  });\n  \n  if (d.alternateFlows && d.alternateFlows.length > 0) {\n    markdown += `\\n### Alternate Flows\\n\\n`;\n    d.alternateFlows.forEach((alt, altIdx) => {\n      markdown += `#### ${altIdx + 1}. ${alt.condition}\\n\\n`;\n      markdown += `| # | From | To | Action |\\n`;\n      markdown += `|---|------|-----|--------|\\n`;\n      (alt.steps || []).forEach((step, stepIdx) => {\n        markdown += `| ${stepIdx + 1} | ${step.from} | ${step.to} | ${step.action} |\\n`;\n      });\n      markdown += `\\n`;\n    });\n  }\n  \n  markdown += `### Validation\\n\\n`;\n  if (d.validation.allComponentsMapped) {\n    markdown += `✅ All participants mapped to application components\\n`;\n  } else {\n    allValid = false;\n    markdown += `⚠️ Missing component mappings: ${d.validation.missingComponents.join(', ')}\\n`;\n  }\n  markdown += `\\n---\\n\\n`;\n});\n\nreturn [{\n  json: {\n    sequenceDiagrams: validatedDiagrams,\n    markdown: markdown,\n    diagramCount: validatedDiagrams.length,\n    allValid: allValid\n  }\n}];"
          }
        },
